            dMatch(pMatch(), [['primary', L('Colore principale', 'Main colour')], ['on-primary', L('Testo sopra primary', 'Text on primary')], ['surface', L('Sfondo delle superfici', 'Surface background')], ['dynamicLightColorScheme', L('Colori dallo sfondo', 'Colours from the wallpaper')], ['colorSchemeSeed', L('Colore seme in Flutter', 'Seed colour in Flutter')]], L('Material nel codice.', 'Material in code.')),
            dFlash(pFlash(), [[L('Il Theme Builder esporta variabili CSS', 'The Theme Builder exports CSS variables'), true], [L('Il colore dinamico funziona su ogni versione di Android', 'Dynamic colour works on every Android version'), false], [L('on-surface va sul testo sopra surface', 'on-surface goes on text over surface'), true], [L('Material 3 richiede di scegliere ogni colore a mano', 'Material 3 requires picking every colour by hand'), false]], L('Dal seme alla palette.', 'From seed to palette.')),
        ]),
        lesson('expressive', L('Material 3 Expressive', 'Material 3 Expressive'), [
            P('**Material 3 Expressive**, presentato nel 2025 e arrivato con Android 16, è un’espansione di M3 basata su decine di studi con migliaia di partecipanti: interfacce più emotive ma anche più facili da usare, in cui gli elementi chiave si notano prima. Non sostituisce M3 e non cambia i ruoli di colore: aggiunge **forme**, **movimento**, **tipografia** e **componenti**.', '**Material 3 Expressive**, introduced in 2025 and shipped with Android 16, is an expansion of M3 based on dozens of studies with thousands of participants: more emotional interfaces that are also easier to use, where key elements are noticed sooner. It does not replace M3 or change the colour roles: it adds **shapes**, **motion**, **typography** and **components**.'),
            P('Le novità principali: una libreria di **35 forme** (non solo rettangoli arrotondati) che possono **trasformarsi** l’una nell’altra, per esempio quando si preme un pulsante; il **movimento a molla** (spring), con uno schema standard e uno espressivo, al posto di curve e durate fisse; stili tipografici **enfatizzati** per dare più peso ai titoli; nuovi componenti come **button group**, **split button**, **FAB menu**, **toolbar** fluttuanti e il **loading indicator**, che sostituisce molti spinner per le attese brevi. La navigation bar diventa più bassa e la **rail espansa** prende il posto del navigation drawer.', 'The main additions: a library of **35 shapes** (not just rounded rectangles) that can **morph** into each other, for example when a button is pressed; **spring motion**, with a standard and an expressive scheme, instead of fixed curves and durations; **emphasised** type styles to give headings more weight; new components such as **button groups**, **split buttons**, the **FAB menu**, floating **toolbars** and the **loading indicator**, which replaces many spinners for short waits. The navigation bar gets shorter and the **expanded rail** takes the place of the navigation drawer.'),
            Tip('Espressivo non vuol dire decorato: usa forme e movimento per guidare l’attenzione sull’azione importante, non su tutto.', 'Expressive does not mean decorated: use shape and motion to draw attention to the important action, not to everything.'),
        ], [
            Q('e1', L('Che cos’è Material 3 Expressive?', 'What is Material 3 Expressive?'), [L('Un nuovo design system che sostituisce M3', 'A new design system replacing M3'), L('Un’espansione di M3 con forme, movimento e componenti nuovi', 'An expansion of M3 with new shapes, motion and components'), L('Un tema scuro per Android', 'A dark theme for Android'), L('Un font di Google', 'A Google typeface')], 1, L('M3 resta la base.', 'M3 remains the foundation.')),
            Q('e2', L('Su che cosa si basa il movimento in M3 Expressive?', 'What is motion based on in M3 Expressive?'), [L('Durate fisse di 300 ms', 'Fixed 300 ms durations'), L('Curve lineari', 'Linear curves'), L('Molle (spring)', 'Springs'), L('Animazioni GIF', 'GIF animations')], 2, L('Più naturale e interrompibile.', 'More natural and interruptible.')),
            Q('e3', L('Quale componente prende il posto del navigation drawer?', 'Which component takes the place of the navigation drawer?'), [L('Il FAB menu', 'The FAB menu'), L('La snackbar', 'The snackbar'), L('Lo split button', 'The split button'), L('La rail espansa', 'The expanded rail')], 3, L('Si adatta meglio alle classi di larghezza.', 'It adapts better across width classes.')),
        ], task('text', L('Elenca tre componenti nuovi di Material 3 Expressive, uno per riga con `-`.', 'List three new Material 3 Expressive components, one per line with `-`.'), "- \n- \n- ", [re('^-[ \t]*\S.*\n-[ \t]*\S.*\n-[ \t]*\S', L('Tre righe', 'Three lines')), re('(button group|gruppo di pulsanti|split button|fab menu|toolbar|loading indicator|indicatore di caricamento)[\s\S]*\n-[^\n]*(button group|gruppo di pulsanti|split button|fab menu|toolbar|loading indicator|indicatore di caricamento)', L('Almeno due componenti nuovi', 'At least two new components'))], '', "- button group\n- split button\n- FAB menu"), [
            dMatch(pMatch(), [['Button group', L('Pulsanti che reagiscono insieme', 'Buttons that react together')], ['Split button', L('Azione più menu di varianti', 'Action plus a menu of variants')], ['FAB menu', L('Il FAB apre più azioni', 'The FAB opens several actions')], ['Loading indicator', L('Attesa breve al posto dello spinner', 'Short wait instead of a spinner')], [L('Rail espansa', 'Expanded rail'), L('Navigazione con etichette', 'Labelled navigation')]], L('I componenti espressivi.', 'The expressive components.')),
            dFlash(pFlash(), [[L('M3 Expressive aggiunge forme che si trasformano', 'M3 Expressive adds morphing shapes'), true], [L('M3 Expressive cambia tutti i ruoli di colore', 'M3 Expressive changes every colour role'), false], [L('Il movimento a molla sostituisce curve e durate fisse', 'Spring motion replaces fixed curves and durations'), true], [L('Espressivo significa decorare ogni elemento', 'Expressive means decorating every element'), false]], L('Espressivo con uno scopo.', 'Expressive with a purpose.')),
        ]),
        lesson('states', L('Stati, icone e accessibilità', 'States, icons and accessibility'), [
            P('In M3 gli stati interattivi si mostrano con lo **state layer**: un velo del colore del contenuto (il ruolo «on») con un’opacità fissa sopra il componente, **8%** al passaggio del puntatore, **10%** per focus e pressione, **16%** durante il trascinamento. Il disattivato usa on-surface al **38%** per il contenuto e al **12%** per il contenitore. Così ogni stato funziona con qualsiasi colore del tema.', 'In M3 interactive states are shown with the **state layer**: a veil of the content colour (the “on” role) with a fixed opacity over the component, **8%** on hover, **10%** for focus and press, **16%** while dragging. Disabled uses on-surface at **38%** for content and **12%** for the container. That way every state works with any theme colour.'),
            P('Le icone sono i **Material Symbols**, un font variabile con quattro assi: **FILL** (vuota o piena: la piena indica spesso lo stato selezionato), **wght** (peso), **GRAD** (grado, per ritocchi fini come sul tema scuro) e **opsz** (dimensione ottica, da 20 a 48). Per l’accessibilità M3 chiede target di almeno **48×48 dp**, coppie di colori «on» che garantiscono il contrasto e un’etichetta per i pulsanti con sola icona.', 'Icons are **Material Symbols**, a variable font with four axes: **FILL** (outlined or filled: filled often marks the selected state), **wght** (weight), **GRAD** (grade, for fine adjustments such as on dark themes) and **opsz** (optical size, from 20 to 48). For accessibility M3 asks for targets of at least **48×48 dp**, “on” colour pairs that guarantee contrast and a label for icon-only buttons.'),
            C('.icona {
  font-family: "Material Symbols Outlined";
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 24;
}
.icona.selezionata {
  font-variation-settings: "FILL" 1, "wght" 500, "GRAD" 0, "opsz" 24;
}', 'css'),
        ], [
            Q('s1', L('Che cos’è uno state layer?', 'What is a state layer?'), [L('Un livello di un file Figma', 'A layer in a Figma file'), L('Un velo semitrasparente che mostra lo stato', 'A semi-transparent veil that shows the state'), L('Un’ombra sotto il componente', 'A shadow under the component'), L('Un tipo di pulsante', 'A kind of button')], 1, L('Hover, focus, pressione, trascinamento.', 'Hover, focus, press, drag.')),
            Q('s2', L('Quale asse dei Material Symbols rende un’icona piena?', 'Which Material Symbols axis makes an icon filled?'), ['wght', 'opsz', 'FILL', 'GRAD'], 2, L('0 vuota, 1 piena.', '0 outlined, 1 filled.')),
            Q('s3', L('Che opacità ha il contenuto di un componente disattivato in M3?', 'What opacity does a disabled component’s content have in M3?'), ['100%', '80%', '5%', '38%'], 3, L('Il contenitore al 12%.', 'The container at 12%.')),
        ], task('css', L('Mostra l’icona come selezionata: alla `.icona` dai `font-variation-settings` con `"FILL" 1` e `"wght" 500`.', 'Show the icon as selected: give `.icona` `font-variation-settings` with `"FILL" 1` and `"wght" 500`.'), ".icona {\n  font-variation-settings: \"FILL\" 0, \"wght\" 400;\n}\n", [re('\.icona\s*\{[^}]*font-variation-settings\s*:[^;]*["\x27]FILL["\x27]\s+1\b', L('Icona piena', 'Filled icon')), re('\.icona\s*\{[^}]*font-variation-settings\s*:[^;]*["\x27]wght["\x27]\s+500\b', L('Peso 500', 'Weight 500'))], '<span class="icona">favorite</span>', ".icona {\n  font-variation-settings: \"FILL\" 1, \"wght\" 500;\n}"), [
            dMatch(pMatch(), [['Hover', '8%'], ['Focus', '10%'], [L('Trascinamento', 'Dragged'), '16%'], [L('Contenuto disattivato', 'Disabled content'), '38%'], ['FILL', L('Icona vuota o piena', 'Outlined or filled icon')]], L('Stati e icone.', 'States and icons.')),
            dFlash(pFlash(), [[L('Lo state layer usa il colore «on» del contenuto', 'The state layer uses the content’s “on” colour'), true], [L('In M3 ogni stato ha un colore scelto a mano', 'In M3 every state has a hand-picked colour'), false], [L('I Material Symbols sono un font variabile', 'Material Symbols are a variable font'), true], [L('Un pulsante con sola icona non ha bisogno di etichetta', 'An icon-only button needs no label'), false]], L('Coerenza in ogni stato.', 'Consistency in every state.')),
        ]),
    ],
